// src/core/matching/matching.types.ts
// Tipos para Matching Humano

export type MatchType = 
  | 'exploration'    // Matching de exploração
  | 'learning'       // Matching de aprendizado
  | 'mirroring';     // Matching de espelhamento

export interface MatchUser {
  userId: string;
  name: string;
  avatar?: string;
  state: string; // Estado inferido
  affinity: {
    physical?: string[];    // Categorias de Físico em comum
    learning?: string[];   // Categorias de Aprendizado em comum
    professional?: string[]; // Categorias Profissionais em comum
  };
  lastActivity?: string;
}

export interface MatchSuggestion {
  id: string;
  type: MatchType;
  users: MatchUser[]; // 1 usuário ou pequeno grupo (max 3)
  title: string; // Título humano
  message: string; // Mensagem contextual
  affinityScore: number; // 0-10, interno, não exibido
  priority: number; // 1-10, maior = mais relevante
  createdAt: string;
}

export interface MatchResult {
  suggestions: MatchSuggestion[];
  hasMore: boolean;
}


























